<?php declare(strict_types=1); namespace App\Services\Pmbm; use App\Enums\Pmbm\ApplicantStatus; use App\Models\{AcademicYear,Student,User}; use App\Models\Pmbm\{PmbmApplicant,PmbmApplicantDocument,PmbmSetting,PmbmStatusHistory}; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\{DB,Storage}; use Illuminate\Validation\ValidationException;
class PmbmRegistrationService { public function submit(array $data,string $source,?User $actor=null):PmbmApplicant{return DB::transaction(function()use($data,$source,$actor){$setting=PmbmSetting::query()->where('academic_year_id',$data['academic_year_id'])->lockForUpdate()->first();if(!$setting||!$setting->enabled||($source==='online'&&!$setting->online_registration_enabled)||($source==='offline'&&!$setting->offline_registration_enabled))throw ValidationException::withMessages(['academic_year_id'=>'Pendaftaran PMBM untuk tahun ajaran ini belum tersedia.']);$year=AcademicYear::findOrFail($data['academic_year_id']);$documents=$data['documents']??[];unset($data['documents'],$data['consent']);$start=$year->starts_at->format('Y');$prefix=$setting->registration_prefix.'-'.$start.'-';$sequence=PmbmApplicant::where('academic_year_id',$year->id)->lockForUpdate()->count()+1;$number=$prefix.str_pad((string)$sequence,4,'0',STR_PAD_LEFT);$applicant=PmbmApplicant::create(['academic_year_id'=>$year->id,'registration_number'=>$number,'registration_source'=>$source,'status'=>ApplicantStatus::Draft,'full_name'=>$data['full_name'],'nickname'=>$data['nickname']??null,'nik'=>$data['nik']??null,'nisn'=>$data['nisn']??null,'gender'=>$data['gender'],'birth_place'=>$data['birth_place'],'birth_date'=>$data['birth_date'],'parent_email'=>$data['parent_email']??null,'parent_phone'=>$data['parent_phone'],'data'=>$data,'submitted_at'=>now(),'consent_at'=>now(),'public_token'=>bin2hex(random_bytes(32)),'created_by'=>$actor?->id]);foreach($documents as $type=>$file)if($file instanceof UploadedFile){$path=$file->store('pmbm/'.$applicant->id,'local');PmbmApplicantDocument::create(['applicant_id'=>$applicant->id,'document_type'=>$type,'original_name'=>$file->getClientOriginalName(),'path'=>$path]);}$this->transition($applicant,ApplicantStatus::Submitted,$actor,'Pendaftaran dikirim.');activity('pmbm')->causedBy($actor)->performedOn($applicant)->log('Pendaftaran PMBM dibuat.');return $applicant;});} public function transition(PmbmApplicant $applicant,ApplicantStatus $status,?User $actor,string $note=''):void{$from=$applicant->status?->value;$applicant->update(['status'=>$status]);PmbmStatusHistory::create(['applicant_id'=>$applicant->id,'from_status'=>$from,'to_status'=>$status->value,'changed_by'=>$actor?->id,'note'=>$note,'changed_at'=>now()]);} public function enroll(PmbmApplicant $applicant,User $actor):Student{return DB::transaction(function()use($applicant,$actor){$applicant=PmbmApplicant::lockForUpdate()->findOrFail($applicant->id);if($applicant->student)return $applicant->student;if($applicant->status!==ApplicantStatus::Registered)throw ValidationException::withMessages(['status'=>'Calon murid harus menyelesaikan daftar ulang sebelum dikonversi.']);if($applicant->nik&&Student::where('nik',$applicant->nik)->exists())throw ValidationException::withMessages(['nik'=>'NIK sudah terdaftar sebagai siswa.']);$d=$applicant->data;$student=Student::create(['full_name'=>$applicant->full_name,'nisn'=>$applicant->nisn,'nik'=>$applicant->nik,'birth_place'=>$applicant->birth_place,'birth_date'=>$applicant->birth_date,'gender'=>$applicant->gender,'address'=>$d['address']??null,'phone'=>$applicant->parent_phone,'special_needs'=>$d['special_needs']??null,'father_name'=>$d['father_name']??null,'mother_name'=>$d['mother_name']??null,'guardian_name'=>$d['guardian_name']??null,'status'=>'active','created_by'=>$actor->id,'updated_by'=>$actor->id]);$applicant->update(['student_id'=>$student->id,'enrolled_by'=>$actor->id,'enrolled_at'=>now()]);$this->transition($applicant,ApplicantStatus::Enrolled,$actor,'Dikonversi menjadi siswa.');activity('pmbm')->causedBy($actor)->performedOn($applicant)->log('Calon murid dikonversi menjadi siswa.');return $student;});} }
